package main

import (
    "encoding/json"
    "fmt"
    "net/http"

    "github.com/pilot-protocol/common/driver"
)

func main() {
    d, err := driver.Connect("")
    if err != nil {
        panic(err)
    }

    // The daemon reports this agent's own address via Info()
    info, _ := d.Info()
    addr, _ := info["address"].(string)

    // Listen on Pilot port 80
    ln, err := d.Listen(80)
    if err != nil {
        panic(err)
    }
    defer ln.Close()

    mux := http.NewServeMux()

    mux.HandleFunc("/api/status", func(w http.ResponseWriter, r *http.Request) {
        w.Header().Set("Content-Type", "application/json")
        json.NewEncoder(w).Encode(map[string]any{
            "status":  "healthy",
            "agent":   addr,
            "version": "1.0.0",
        })
    })

    mux.HandleFunc("/api/echo", func(w http.ResponseWriter, r *http.Request) {
        w.Header().Set("Content-Type", "application/json")
        var body map[string]any
        json.NewDecoder(r.Body).Decode(&body)
        json.NewEncoder(w).Encode(body)
    })

    fmt.Printf("HTTP server listening on pilot port 80 (%s)\n", addr)
    http.Serve(ln, mux)
}

package main

import (
    "bufio"
    "fmt"
    "io"
    "net/http"

    "github.com/pilot-protocol/common/driver"
)

func main() {
    d, err := driver.Connect("")
    if err != nil {
        panic(err)
    }

    // Dial Agent A's address on port 80 (addr string is "N:XXXX.YYYY.YYYY:PORT")
    conn, err := d.Dial("0:0000.0002.0003:80")
    if err != nil {
        panic(err)
    }
    defer conn.Close()

    // Send a standard HTTP request over the Pilot connection
    req, _ := http.NewRequest("GET", "http://agent-a/api/status", nil)
    req.Write(conn)

    // Read the standard HTTP response
    resp, err := http.ReadResponse(bufio.NewReader(conn), req)
    if err != nil {
        panic(err)
    }
    defer resp.Body.Close()

    body, _ := io.ReadAll(resp.Body)
    fmt.Printf("Status: %d\nBody: %s\n", resp.StatusCode, body)
}

package main

import (
    "context"
    "fmt"
    "io"
    "net"
    "net/http"

    "github.com/pilot-protocol/common/driver"
)

func main() {
    d, _ := driver.Connect("")

    // Custom transport that dials through Pilot
    transport := &http.Transport{
        DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
            // addr is "hostname:port" - resolve hostname via registry
            host, _, _ := net.SplitHostPort(addr)
            info, err := d.ResolveHostname(host)
            if err != nil {
                return nil, err
            }
            return d.Dial(fmt.Sprintf("%s:80", info["address"]))
        },
    }

    client := &http.Client{Transport: transport}

    // Now use standard HTTP client methods
    resp, err := client.Get("http://agent-a/api/status")
    if err != nil {
        panic(err)
    }
    defer resp.Body.Close()

    body, _ := io.ReadAll(resp.Body)
    fmt.Printf("%s\n", body)
}

package main

import (
    "encoding/json"
    "net/http"

    "github.com/pilot-protocol/common/driver"
)

type User struct {
    ID    string `json:"id"`
    Name  string `json:"name"`
    Email string `json:"email"`
}

var users = map[string]User{
    "u1": {ID: "u1", Name: "Alice", Email: "alice@example.com"},
    "u2": {ID: "u2", Name: "Bob", Email: "bob@example.com"},
}

func main() {
    d, _ := driver.Connect("")
    ln, _ := d.Listen(80)

    mux := http.NewServeMux()

    mux.HandleFunc("/api/users/", func(w http.ResponseWriter, r *http.Request) {
        id := r.URL.Path[len("/api/users/"):]
        w.Header().Set("Content-Type", "application/json")
        if user, ok := users[id]; ok {
            json.NewEncoder(w).Encode(user)
        } else {
            w.WriteHeader(404)
            json.NewEncoder(w).Encode(map[string]string{"error": "not found"})
        }
    })

    mux.HandleFunc("/api/users", func(w http.ResponseWriter, r *http.Request) {
        w.Header().Set("Content-Type", "application/json")
        all := make([]User, 0, len(users))
        for _, u := range users {
            all = append(all, u)
        }
        json.NewEncoder(w).Encode(all)
    })

    http.Serve(ln, mux)
}

package main

import (
    "encoding/json"
    "net/http"

    "github.com/pilot-protocol/common/driver"
)

type Order struct {
    ID     string  `json:"id"`
    UserID string  `json:"user_id"`
    Item   string  `json:"item"`
    Total  float64 `json:"total"`
    Status string  `json:"status"`
}

var orders = []Order{
    {ID: "o1", UserID: "u1", Item: "GPU Cluster Hours", Total: 250.00, Status: "completed"},
    {ID: "o2", UserID: "u2", Item: "Dataset License", Total: 75.00, Status: "pending"},
    {ID: "o3", UserID: "u1", Item: "Model Training Run", Total: 1200.00, Status: "active"},
}

func main() {
    d, _ := driver.Connect("")
    ln, _ := d.Listen(80)

    mux := http.NewServeMux()

    mux.HandleFunc("/api/orders", func(w http.ResponseWriter, r *http.Request) {
        w.Header().Set("Content-Type", "application/json")
        userID := r.URL.Query().Get("user_id")
        if userID == "" {
            json.NewEncoder(w).Encode(orders)
            return
        }
        var filtered []Order
        for _, o := range orders {
            if o.UserID == userID {
                filtered = append(filtered, o)
            }
        }
        json.NewEncoder(w).Encode(filtered)
    })

    http.Serve(ln, mux)
}

package main

import (
    "encoding/json"
    "net/http"

    "github.com/pilot-protocol/common/driver"
)

type InventoryItem struct {
    SKU       string `json:"sku"`
    Name      string `json:"name"`
    Available int    `json:"available"`
}

var inventory = []InventoryItem{
    {SKU: "gpu-a100", Name: "GPU Cluster Hours (A100)", Available: 48},
    {SKU: "dataset-01", Name: "ImageNet License", Available: 999},
    {SKU: "train-spot", Name: "Spot Training Instance", Available: 12},
}

func main() {
    d, _ := driver.Connect("")
    ln, _ := d.Listen(80)

    mux := http.NewServeMux()

    mux.HandleFunc("/api/inventory", func(w http.ResponseWriter, r *http.Request) {
        w.Header().Set("Content-Type", "application/json")
        json.NewEncoder(w).Encode(inventory)
    })

    mux.HandleFunc("/api/inventory/check", func(w http.ResponseWriter, r *http.Request) {
        sku := r.URL.Query().Get("sku")
        w.Header().Set("Content-Type", "application/json")
        for _, item := range inventory {
            if item.SKU == sku {
                json.NewEncoder(w).Encode(map[string]any{
                    "sku":       item.SKU,
                    "available": item.Available > 0,
                    "count":     item.Available,
                })
                return
            }
        }
        w.WriteHeader(404)
        json.NewEncoder(w).Encode(map[string]string{"error": "sku not found"})
    })

    http.Serve(ln, mux)
}

// Inside the Orders service: enrich order with user details
func enrichOrder(d *driver.Driver, order Order) map[string]any {
    conn, _ := d.Dial("0:0000.0002.0001:80") // Users service
    defer conn.Close()

    req, _ := http.NewRequest("GET",
        fmt.Sprintf("http://users/api/users/%s", order.UserID), nil)
    req.Write(conn)

    resp, _ := http.ReadResponse(bufio.NewReader(conn), req)
    defer resp.Body.Close()

    var user User
    json.NewDecoder(resp.Body).Decode(&user)

    return map[string]any{
        "order": order,
        "user":  user,
    }
}

